function Invoke-ProSoakDispatchRepair($Session,$Guard,[string]$ProNonce,[string]$ScriptDirectory,[bool]$Resume=$false){
 $meta=$Guard.ReadCommand('soak-inputs.json')|ConvertFrom-Json;$reader=$Guard.ReadCommand('volume-reader-inputs.json')|ConvertFrom-Json;if($meta.caseId -notmatch '^[a-f0-9]{32}$' -or $reader.caseId -notmatch '^[a-f0-9]{32}$' -or $meta.proNonce -ne $ProNonce -or $reader.proNonce -ne $ProNonce){throw 'Exact stopped soak and known broker reference required'}
 $source=Join-Path $ScriptDirectory 'install-broker.ps1';$Guard.PinInputFile($source);$sha=(Get-FileHash $source).Hash.ToLowerInvariant();$target='C:\MuLab\private\soak-'+$meta.caseId+'-dispatch-installer.ps1'
 $exists=Invoke-Command -Session $Session -ArgumentList $target,$Resume,$sha -ScriptBlock {param($target,$resume,$sha) $exists=Test-Path $target;if($exists -ne $resume -or ($exists -and (Get-FileHash $target).Hash.ToLowerInvariant() -ne $sha)){throw 'Prior dispatch repair must be inspected'};return $exists};if(-not $exists){Copy-Item -LiteralPath $source -Destination $target -ToSession $Session}
 return Invoke-Command -Session $Session -ArgumentList $meta.caseId,$reader.caseId,$meta.sourceDigest,$target,$sha,$Resume -ScriptBlock {
  param($caseId,$referenceCase,$expectedDigest,$installer,$sha,$resume)
  $ErrorActionPreference='Stop';$approved='C:\MuLab\approved\soak-'+$caseId;$cfg=[IO.File]::ReadAllText($approved+'-config.json')|ConvertFrom-Json;$result=[IO.File]::ReadAllText($approved+'-result.json')|ConvertFrom-Json;$expected=([IO.File]::ReadAllText(('C:\MuLab\approved\volume-'+$referenceCase+'-config.json'))|ConvertFrom-Json).broker;$vm=Get-VM -Id ([guid]$result.nested.platformId)
  if($result.caseId -ne $caseId -or $result.complete -ne $false -or -not $result.processExitConfirmed -or -not $result.brokerExitConfirmed -or -not $result.nested.confirmedOff -or $vm.State -ne 'Off' -or @(Get-VM).Count -ne 1 -or $expected.sourceDigest -ne $expectedDigest -or $expected.brokerFile -notmatch '^hv-broker-[a-f0-9]{16}\.exe$' -or $expected.channelFile -notmatch '^hv-channel-[a-f0-9]{16}\.exe$' -or (Get-FileHash $installer).Hash.ToLowerInvariant() -ne $sha){throw 'Dispatch restoration identity changed'}
  if(@(Get-CimInstance Win32_Process|Where-Object{$_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-*.exe' -or ($_.ExecutablePath -eq 'C:\MuLab\product\resources\node\node.exe' -and $_.CommandLine -like '*client.mjs soak-preserve*')}).Count){throw 'A prior legacy actor remains live'}
  $bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';$current=[IO.File]::ReadAllText((Join-Path $bin 'current.json'))|ConvertFrom-Json;$broker=Join-Path $bin $expected.brokerFile;$channel=Join-Path $bin $expected.channelFile
  if((Get-FileHash $broker).Hash.ToLowerInvariant() -ne $expected.brokerSha256 -or (Get-FileHash $channel).Hash.ToLowerInvariant() -ne $expected.channelSha256){throw 'Known protected binary digest changed'}
  $root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$cfg.userSid);$ledger=(Get-FileHash (Join-Path $root 'vms.json')).Hash;$backup=(Get-FileHash (Join-Path $root 'vms.backup.json')).Hash;$task=Get-ScheduledTask -TaskName 'MuPro-soak-preserve' -ErrorAction SilentlyContinue;$taskXml=$null
  if($task){if($task.State -eq 'Running' -or @($task.Actions).Count -ne 1 -or $task.Actions.Execute -ne 'C:\MuLab\product\resources\node\node.exe' -or $task.Actions.Arguments -ne '--no-warnings C:\MuLab\client.mjs soak-preserve'){throw 'Unexpected task preserved'};$taskXml=Export-ScheduledTask -TaskName $task.TaskName}
  $before=@{caseId=$caseId;current=$current;expected=$expected;ledgerSha256=$ledger;backupSha256=$backup;unexpectedTask=$taskXml};$file='C:\MuLab\private\soak-'+$caseId+'-dispatch-before.json';if($resume){$before=[IO.File]::ReadAllText($file)|ConvertFrom-Json;if($before.caseId -ne $caseId -or $before.ledgerSha256 -ne $ledger -or $before.backupSha256 -ne $backup -or $before.expected.sourceDigest -ne $expected.sourceDigest){throw 'Original repair snapshot changed'}}else{$stream=[IO.File]::Open($file,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$bytes=[Text.UTF8Encoding]::new($false).GetBytes(($before|ConvertTo-Json -Depth 8));$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()}}
  if($current.sourceDigest -ne $expectedDigest){& ([ScriptBlock]::Create([IO.File]::ReadAllText($installer))) -Broker $broker -ExpectedBrokerHash $expected.brokerSha256 -Channel $channel -ExpectedChannelHash $expected.channelSha256 -SourceDigest $expected.sourceDigest}
  $after=[IO.File]::ReadAllText((Join-Path $bin 'current.json'))|ConvertFrom-Json;foreach($key in @('sourceDigest','brokerFile','brokerSha256','channelFile','channelSha256')){if($after.$key -cne $expected.$key){throw 'Broker restoration not confirmed'}};if((Get-FileHash (Join-Path $root 'vms.json')).Hash -ne $ledger -or (Get-FileHash (Join-Path $root 'vms.backup.json')).Hash -ne $backup -or (Get-VM -Id $vm.Id).State -ne 'Off'){throw 'Original resources changed during dispatcher repair'}
  if($task){Unregister-ScheduledTask -TaskName $task.TaskName -Confirm:$false};return @{complete=$true;caseId=$caseId;sourceDigestBefore=$current.sourceDigest;sourceDigestAfter=$after.sourceDigest;brokerRestored=$true;unexpectedTaskRemoved=[bool]$task;originalVmOff=$true;originalLedgersUnchanged=$true}
 }
}
